from itertools import count

def first_digit(n: int) -> int:
    while n >= 10:
        n //= 10
    return n

def last_digit(n: int) -> int:
    return n % 10

def is_odd(d: int) -> bool:
    return d % 2 == 1

def count_numbers_gt_10_with_odd_first_and_last(limit: int) -> int:
    # Count numbers n > 10 and n <= limit with odd first and last digits
    return sum(
        1 for n in range(11, limit + 1)
        if is_odd(first_digit(n)) and is_odd(last_digit(n))
    )

# Example usage:
if __name__ == "__main__":
    limit = 1000  # change as needed
    print(count_numbers_gt_10_with_odd_first_and_last(limit))
