def rescale_to_unit_interval(data):
    data = list(data)
    if not data:
        return []
    lo = min(data)
    hi = max(data)
    if lo == hi:
        return [0.0 for _ in data]
    return list(map(lambda x: (x - lo) / (hi - lo), data))

