import numpy as np

def rescale_to_unit_interval_np(data):
    arr = np.asarray(data, dtype=float)
    lo = arr.min()
    hi = arr.max()
    if lo == hi:
        return np.zeros_like(arr, dtype=float)
    return (arr - lo) / (hi - lo)

